from pathlib import Path
base=Path('/home/iotim/chika-curation');root=Path(__file__).parent
state={'pid':os.getpid(),'status':'running','started_at':time.time(),'languages':{}}
def save():
 p=root/'worker.tmp';p.write_text(json.dumps(state,indent=2));p.replace(root/'worker.json')
save()
