 for lang,channel in [('cebuano','UCVoawkpW12kgtXgInbPCrhQ'),('bikolano','UCVoawkpW12kgtXgInbPCrhQ'),('ilocano','UCE2606prvXQc_noEqKxVJXA')]:
  source=base/(lang+'.json');data=json.loads(source.read_text());accepted=[];rejected=[];dest=root/lang;dest.mkdir()
