   except Exception as e: rejected.append({'id':ident,'reason':str(e)})
   state['languages'][lang]={'accepted':len(accepted),'rejected':len(rejected),'processed':len(accepted)+len(rejected)};save()
   (dest/'result.json').write_text(json.dumps({'input_sha256':hashlib.sha256(source.read_bytes()).hexdigest(),'expected_channel':channel,'items':accepted,'rejected':rejected,'scope':'metadata preflight only; no audio acquired or language verified'},indent=2))
